-- Ejecutar en el editor SQL de Supabase después de autenticacion_perfiles.sql.
-- Las reservas pueden corresponder a productos aún no registrados en inventario.
BEGIN;
CREATE TABLE IF NOT EXISTS public.reserva_producto (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- Identifica la reserva sin reutilizar el código como clave.
  codigo_producto text NOT NULL CHECK (length(btrim(codigo_producto)) > 0), -- Admite códigos alfanuméricos del proveedor.
  rut_cliente integer NOT NULL REFERENCES public.cliente(rut), -- Identifica a quién avisar y reutiliza su teléfono.
  estado text NOT NULL DEFAULT 'reservado' CHECK (estado IN ('reservado', 'lista')), -- Conserva la transición sin eliminar registros.
  fecha_registro timestamptz NOT NULL DEFAULT now() -- Conserva cuándo se solicitó la reserva.
);
ALTER TABLE public.reserva_producto ADD COLUMN IF NOT EXISTS rut_cliente integer REFERENCES public.cliente(rut); -- Permite actualizar una instalación previa sin inventar clientes.
DROP INDEX IF EXISTS public.reserva_producto_codigo_pendiente; -- Sustituye la unicidad global por la correspondiente a cada cliente.
-- Evita dos reservas pendientes del mismo código, incluso con diferencias de mayúsculas.
CREATE UNIQUE INDEX IF NOT EXISTS reserva_producto_codigo_pendiente ON public.reserva_producto (upper(btrim(codigo_producto)), rut_cliente) WHERE estado = 'reservado';
ALTER TABLE public.reserva_producto ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS consultar_reservas ON public.reserva_producto;
CREATE POLICY consultar_reservas ON public.reserva_producto FOR SELECT TO authenticated USING ((SELECT public.rol_actual()) IN ('administrador', 'empleado'));
DROP POLICY IF EXISTS crear_reservas ON public.reserva_producto;
CREATE POLICY crear_reservas ON public.reserva_producto FOR INSERT TO authenticated WITH CHECK ((SELECT public.rol_actual()) IN ('administrador', 'empleado') AND estado = 'reservado' AND rut_cliente IS NOT NULL);
DROP POLICY IF EXISTS completar_reservas ON public.reserva_producto;
CREATE POLICY completar_reservas ON public.reserva_producto FOR UPDATE TO authenticated USING ((SELECT public.rol_actual()) IN ('administrador', 'empleado') AND estado = 'reservado') WITH CHECK ((SELECT public.rol_actual()) IN ('administrador', 'empleado') AND estado = 'lista');
REVOKE ALL ON public.reserva_producto FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON public.reserva_producto TO authenticated;
GRANT DELETE ON public.reserva_producto TO authenticated; -- RLS limita la eliminación al administrador.
GRANT UPDATE (estado) ON public.reserva_producto TO authenticated; -- Solo permite modificar el estado desde la aplicación.
GRANT USAGE ON SEQUENCE public.reserva_producto_id_seq TO authenticated; -- Permite asignar IDs sin claves administrativas.
COMMIT;
